output_text:
[
  {
    "id": "must_take_cart",
    "text": "A shopper starting a multi-item trip must take the available cart before doing the shopping.",
    "abstraction": {
      "state_properties": {
        "at_cart_stack": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "at_cart_stack",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Required shelf items should be picked up only while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_pickup"
    }
  },
  {
    "id": "return_cart_after_use",
    "text": "Once a shopper has taken a cart, they must return it to the cart-return cell before leaving.",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)",
        "has_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "has_cart"
        },
        "return_cart": {
          "pre": {
            "and": [
              "at_cart_return",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart"
    }
  },
  {
    "id": "cart_only_left_at_return",
    "text": "A cart may not be put down anywhere except the designated return cell.",
    "abstraction": {
      "state_properties": {
        "at_designated_cart_return": "at(0,1)",
        "not_at_designated_cart_return": {
          "not": "at_designated_cart_return"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_designated_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is not allowed to exit the store while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "has_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_loose_hand_carrying",
    "text": "Items should not be carried loose by hand during the shopping trip.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "become_hand_full": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "after_5_2_pickup_go_west",
    "text": "After taking an item from the shelf at cell (5,2), the shopper should turn back west rather than continue east along the aisle.",
    "abstraction": {
      "state_properties": {
        "at_5_2": "at(5,2)",
        "with_cart": "hasCart"
      },
      "events": {
        "pickup_at_5_2": {
          "pre": {
            "and": [
              "at_5_2",
              "with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "leave_5_2_west": {
          "pre": {
            "and": [
              "at_5_2",
              "W"
            ]
          },
          "post": "at(4,2)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_at_5_2",
      "discharge": "leave_5_2_west"
    }
  },
  {
    "id": "after_cart_return_rejoin_front_aisle",
    "text": "After returning the cart, the shopper should go back down to the front aisle before exiting.",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)",
        "front_aisle_entry": "at(0,5)"
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "at_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        },
        "reach_front_aisle_entry": {
          "pre": "front_aisle_entry",
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart",
      "discharge": "reach_front_aisle_entry"
    }
  }
]
